import React, { useEffect } from "react";
import SidebarMenu from "./SidebarMenu";
const Layout = ({ children }) => {
  useEffect(() => {
    if (window.$) {
      window.$(() => window.$('.nav-sidebar').each(function () {
        window.$(this).treeview();
      }));
    }
  }, []);
  return (
    <div className="hold-transition sidebar-mini layout-fixed">
      <nav className="main-header navbar navbar-expand navbar-white navbar-light">
        <ul className="navbar-nav">
          <li className="nav-item">
            <a className="nav-link" data-widget="pushmenu" href="#"><i className="fas fa-bars"></i></a>
          </li>
        </ul>
      </nav>
      <aside className="main-sidebar sidebar-dark-primary elevation-4">
        <a href="/" className="brand-link">
          <img src="template/dist/img/AdminLTELogo.png" className="brand-image img-circle elevation-3" style={{ opacity: ".8" }} alt="AdminLTE" />
          <span className="brand-text font-weight-light">ORA</span>
        </a>
        <div className="sidebar">
          <SidebarMenu />
        </div>
      </aside>
      <div className="content p-3">{children}</div>
    </div>
  );
};

export default Layout;
